/**
 * Jet Hub 多账号管理的 RPC 端点注册。
 *
 * 1. 采用 @deepseek-ai/dsh-typert-protocol 的 TypertRemoteService 暴露原生 Remote 标准服务，
 *    彻底融入 DSH 内部 API Gateway 认证通道。
 * 2. 同时使用 DSH 的 connection.fetch.register() 模式注册 HTTP API 端点作为双通道保障，
 *    通道名 jet-hub → 路径 /api/jet-hub，配置完整 CORS 与 Content-Type 响应头。
 * 端点方法：account.list / account.create / account.update / account.delete / account.refresh / login.poll
 */
import { credentialRef } from '@deepseek-ai/dsh-credentials';
import { Remote, TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol';
import { openBrowser } from './login.js';
import { fetchAuthState, runBuddyLoginFlow } from './buddy-oauth.js';
import { credentialExpiresAtMs, INTL_BUDDY_ENDPOINTS } from './buddy.js';

/** Jet Hub RPC API 路径 */
export const JET_HUB_API_PATH = '/api/jet-hub';
/** Gateway RPC 端点名（connection.rpc.call 的 endpoint 参数） */
const JET_HUB_ENDPOINT = 'jet-hub';

/** 生成 8 字符随机短 ID（小写 hex） */
function shortId() {
    const buf = new Uint8Array(4);
    crypto.getRandomValues(buf);
    return Array.from(buf, (b) => b.toString(16).padStart(2, '0')).join('');
}

/** 解析 Buddy 凭据 JSON；解析失败返回 undefined。 */
function parseBuddyCredential(raw) {
    try {
        const parsed = JSON.parse(raw);
        return typeof parsed === 'object' && parsed !== null && typeof parsed.access_token === 'string'
            ? parsed
            : undefined;
    }
    catch {
        return undefined;
    }
}

/** 业务方法分发函数 */
export async function dispatchJetHubMethod(ctx, pool, codearts, buddy, buddyIntl, method, payload, _signal) {
    switch (method) {
        case 'account.list': {
            const req = payload;
            const accounts = await pool.listAccounts(req.provider);
            return { ok: true, value: { accounts } };
        }
        case 'account.create': {
            const req = payload;
            const { provider } = req;
            const id = `${provider}-${shortId()}`;
            const suffix = shortId().toUpperCase();
            // 凭据 ref 连字符转下划线（POSIX 标识符，如 buddy-intl → BUDDY_INTL）
            const refName = `${provider.replace(/-/g, '_').toUpperCase()}_ACCOUNT_${suffix}`;
            // Buddy 系（国内 'buddy' 与海外 'buddy-intl'）两步登录：只获取 loginUrl 和 state 立即返回，
            // 后台用同一个 state 异步执行完整登录流程
            if (provider === 'buddy' || provider === 'buddy-intl') {
                const apiBase = provider === 'buddy-intl' ? INTL_BUDDY_ENDPOINTS.apiBase : undefined;
                let state;
                let authUrl;
                try {
                    const authState = await fetchAuthState(fetch, undefined, apiBase);
                    state = authState.state;
                    authUrl = authState.authUrl;
                }
                catch (error) {
                    const reason = error instanceof Error ? error.message : String(error);
                    throw new Error(`无法获取 CodeBuddy 登录地址（Host 网络请求失败）：${reason}`);
                }
                const ref = credentialRef(refName);
                // 先在 pool 中添加启用的占位条目（无凭据），方便客户端 login.poll 检测到
                await pool.addAccount({
                    id,
                    provider,
                    nickname: id,
                    enabled: true,
                    credentialRef: refName,
                    refreshable: false,
                    createdAt: Date.now(),
                });
                // 宿主级拉起浏览器：客户端在 await 之后调 window.open 已脱离用户手势的
                // 同步调用栈，弹窗拦截器必拦（实测）；改由 OS 打开器直接拉起默认浏览器
                // （与 codearts 分支同机制），客户端只展示链接兜底并轮询完成状态。
                openBrowser(authUrl);
                // 后台异步执行完整登录流程，使用同一个 state；海外版实例接管调度
                const auth = provider === 'buddy-intl' && buddyIntl !== undefined ? buddyIntl : buddy;
                runBuddyLoginFlow({ openBrowser: () => { }, state, apiBase }).then(async (flow) => {
                    await ctx.credentials.set(ref, flow.access);
                    auth.scheduleRefresh();
                    const credential = parseBuddyCredential(flow.access);
                    await pool.updateAccount(id, {
                        nickname: credential?.nickname ?? id,
                        // Buddy 的 expires_at 是字符串形式的毫秒时间戳，
                        // 必须用 credentialExpiresAtMs 解析（Date.parse 对纯数字串会得到 NaN）。
                        expiresAt: credential ? credentialExpiresAtMs(credential) : undefined,
                        refreshable: Boolean(credential?.refresh_token),
                    });
                }).catch((err) => {
                    ctx.logger?.warn?.(`[jet-hub] background buddy login failed for ${id}: ${err}`);
                    // 登录失败：移除占位条目，避免留下无凭据的幽灵账号
                    void pool.removeAccount(id).catch(() => { });
                });
                return { ok: true, value: { accountId: id, loginUrl: authUrl } };
            }
            else if (provider === 'codearts') {
                // codearts login 是 OAuth 回调方式，不支持纯获取 URL
                // 直接同步执行（需等待回调完成）
                const loginResult = await codearts.login({ refName, accountId: id, pool });
                return { ok: true, value: { accountId: id, loginUrl: loginResult.loginUrl } };
            }
            else {
                return { ok: false, error: { code: 'bad-request', message: `unknown provider: ${provider}` } };
            }
        }
        case 'account.update': {
            const req = payload;
            await pool.updateAccount(req.accountId, req.patch);
            return { ok: true, value: undefined };
        }
        case 'account.delete': {
            const req = payload;
            await pool.removeAccount(req.accountId);
            return { ok: true, value: undefined };
        }
        case 'account.refresh': {
            const req = payload;
            try {
                const accounts = await pool.listAllAccounts();
                const entry = accounts.find((a) => a.id === req.accountId);
                if (!entry)
                    throw new Error(`Account ${req.accountId} not found`);
                if (entry.provider === 'codearts') {
                    await codearts.refresh();
                }
                else if (entry.provider === 'buddy') {
                    await buddy.refresh();
                }
                else if (entry.provider === 'buddy-intl') {
                    if (!buddyIntl)
                        throw new Error('海外版（buddy-intl）服务实例未注册');
                    await buddyIntl.refresh();
                }
                else {
                    throw new Error(`Unknown provider: ${entry.provider}`);
                }
                return { ok: true, value: { success: true } };
            }
            catch (error) {
                return {
                    ok: true,
                    value: {
                        success: false,
                        error: error instanceof Error ? error.message : String(error),
                    },
                };
            }
        }
        case 'login.poll': {
            const req = payload;
            const accounts = await pool.listAllAccounts();
            const entry = accounts.find((a) => a.id === req.accountId);
            if (!entry)
                return { ok: true, value: { done: false } };
            // 检查凭据是否已实际写入（占位条目没有凭据）
            const ref = credentialRef(entry.credentialRef);
            const resolved = await ctx.credentials.resolve(ref);
            if (!resolved)
                return { ok: true, value: { done: false } };
            return { ok: true, value: { done: true, success: true } };
        }
        default:
            return { ok: false, error: { code: 'bad-request', message: `unknown method: ${method}` } };
    }
}

/**
 * Jet Hub 官方 TypertRemoteService 原生实现。
 * 绑定至 namespace: "jetHub"，向 ctx.remote.jetHub 暴露 call 等方法。
 */
export class JetHubRemoteService extends TypertRemoteService {
    constructor(ctx, pool, codearts, buddy, buddyIntl) {
        super(ctx, 'jetHubRemote', { namespace: 'jetHub' });
        this.pool = pool;
        this.codearts = codearts;
        this.buddy = buddy;
        this.buddyIntl = buddyIntl;
    }

    async call(method, payload) {
        return await dispatchJetHubMethod(this.ctx, this.pool, this.codearts, this.buddy, this.buddyIntl, method, payload);
    }
}

// 注册 Remote 原型元数据（兼容无 Babel 装饰器编译的 Node 原生运行时）
function registerRemoteMethod(cls, methodName, exportName) {
    if (typeof Remote === 'function') {
        const decorator = Remote(exportName || methodName);
        const initializers = [];
        decorator(cls.prototype[methodName], {
            kind: 'method',
            name: methodName,
            static: false,
            private: false,
            access: {
                has: (obj) => methodName in obj,
                get: (obj) => obj[methodName],
            },
            addInitializer(init) {
                initializers.push(init);
            },
        });
        const dummyInstance = Object.create(cls.prototype);
        for (const init of initializers) {
            init.call(dummyInstance);
        }
    }
}
registerRemoteMethod(JetHubRemoteService, 'call');

/**
 * 注册 Jet Hub 管理 API 端点。
 * 1. 挂载 JetHubRemoteService 到 Cordis 容器（原生 Remote API 通道）。
 * 2. 使用 ctx.connection.fetch.register() 注册 HTTP POST/OPTIONS 端点（增强型 HTTP RPC 双保险）。
 */
export function registerJetHubRpc(ctx, pool, codearts, buddy, 
/** 海外版 buddy-intl 服务实例（可选；未注册时 buddy-intl 登录仍走通用流程，refresh 报错提示）。 */
buddyIntl) {
    // 1. 注册 TypertRemoteService
    try {
        let service = ctx.get('jetHubRemote');
        if (!service) {
            new JetHubRemoteService(ctx, pool, codearts, buddy, buddyIntl);
        }
    }
    catch (err) {
        ctx.logger?.warn?.(`[jet-hub] failed to register JetHubRemoteService: ${err}`);
    }

    // 2. 注册 HTTP Fetch 端点（带 CORS 与 Content-Type 双重增强）
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const connection = ctx.connection ?? ctx.get('connection');
    if (!connection || typeof connection.fetch?.register !== 'function') {
        ctx.logger?.warn?.('[jet-hub] connection.fetch not available, HTTP RPC endpoint not registered');
        return;
    }
    connection.fetch.register({
        path: JET_HUB_API_PATH,
        methods: ['POST', 'OPTIONS'],
        requestBody: 'buffered',
        async fetch(request) {
            if (request.method === 'OPTIONS') {
                const origin = request.headers.get('origin') || '*';
                return new Response(null, {
                    status: 204,
                    headers: {
                        'access-control-allow-origin': origin,
                        'access-control-allow-credentials': 'true',
                        'access-control-allow-methods': 'POST, OPTIONS',
                        'access-control-allow-headers': 'content-type, authorization, *',
                        'access-control-max-age': '86400',
                    },
                });
            }
            if (request.method !== 'POST') {
                return new Response('method not allowed', { status: 405 });
            }
            const contentType = request.headers.get('content-type')?.split(';', 1)[0].trim().toLowerCase();
            if (contentType !== 'application/json') {
                return new Response('content type must be application/json', { status: 415 });
            }
            let message;
            try {
                message = await request.json();
            }
            catch {
                return new Response('body is not JSON', { status: 400 });
            }
            const rpcId = typeof message.rpcId === 'string' ? message.rpcId : 'invalid-request';
            const call = message.payload;
            if (message.type !== 'client-request' || typeof message.rpcId !== 'string'
                || message.method !== JET_HUB_ENDPOINT
                || !call || typeof call.method !== 'string'
                || !Object.prototype.hasOwnProperty.call(call, 'payload')) {
                return reply(rpcId, { ok: false, error: { code: 'gateway/bad-request', message: 'Invalid Jet Hub management request.' } }, request.headers);
            }
            try {
                const result = await dispatchJetHubMethod(ctx, pool, codearts, buddy, buddyIntl, call.method, call.payload, request.signal);
                return reply(rpcId, result, request.headers);
            }
            catch (error) {
                // 必须返回规范的 RPC 错误响应（而不是裸 500 文本），
                // 否则客户端 unwrapRpcResult 无法识别错误，表现为"点击无反应"。
                const message = error instanceof Error ? error.message : String(error);
                ctx.logger?.warn?.(`[jet-hub] ${String(call.method)} failed: ${message}`);
                return reply(rpcId, {
                    ok: false,
                    error: { code: 'jet-hub/handler-failed', message },
                }, request.headers);
            }
        },
    });
}

/** 构造带 rpcId 的响应 JSON，附加完整 CORS 与 Content-Type */
function reply(rpcId, result, headers) {
    const value = typeof result === 'object' && result !== null && result.ok === false
        ? { ...result, error: { ...result.error, details: result.error?.details ?? {} } }
        : result;
    const origin = headers?.get?.('origin') || '*';
    return new Response(JSON.stringify({ type: 'server-response', rpcId, result: value }), {
        status: 200,
        headers: {
            'content-type': 'application/json; charset=utf-8',
            'access-control-allow-origin': origin,
            'access-control-allow-credentials': 'true',
            'access-control-allow-methods': 'POST, OPTIONS',
            'access-control-allow-headers': 'content-type, authorization, *',
        },
    });
}
